// Tenant-aware GraphQL field resolver with REST backend integration
const resolvers = {
  Query: {
    userData: async (parent, { id }, context) => {
      const { tenantId, featureFlags } = context;

      // Check feature flag before proceeding
      if (!await featureFlags.isEnabled('userData', tenantId)) {
        throw new Error('Feature not available for tenant');
      }

      // Fetch from REST backend with tenant isolation
      return fetch(`/api/v1/tenants/${tenantId}/users/${id}`);
    }
  }
};

// Per-tenant OpenAPI specification fetch
class TenantSpecGenerator {
  async generateTenantSpec(tenantId, version = 'latest') {
    const baseSpec = await this.getBaseSpec();
    const tenantConfig = await this.getTenantConfig(tenantId);

    return {
      ...baseSpec,
      servers: [{ url: `https://${tenantId}.api.example.com` }],
      'x-tenant-id': tenantId,
      'x-version': version,
      paths: this.filterPathsForTenant(baseSpec.paths, tenantConfig)
    };
  }
}
```

## Why This Is Asked
Tests ability to design cross-region sharding and replication with low latency reads, strong intra-region consistency, and safe cross-region merges under failures.

## Key Concepts
- **Shard key**: user_id ensures even data distribution and colocates user events for efficient reads
- **In-region replication**: Raft-style quorum (2 of 3 replicas) provides strong consistency with low-latency writes
- **Global sequencing**: Regional sequencers coordinate via Paxos/Raft to assign monotonically increasing global timestamps
- **Idempotent writes**: Composite key (user_id, global_seq, event_type) deduplicates retried operations
- **Failure handling**: Write-ahead log (WAL) for durability, outbox pattern for atomic cross-region updates, replay queues for recovery, and backpressure to handle traffic spikes

## Code Example
```javascript
// Idempotent event append with cross-region merge
async function appendEvent(event) {
  const globalSeq = await sequencer.nextTimestamp();
  const idempotencyKey = `${event.user_id}:${globalSeq}:${event.event_type}`;

  // Check for duplicates
  if (await cache.exists(idempotencyKey)) {
    return { status: 'duplicate', seq: globalSeq };
  }

  // Write to local region with Raft quorum
  const writeResult = await raftGroup.write({
    key: `shard_${hash(event.user_id)}`,
    value: { ...event, global_seq: globalSeq, idempotency_key: idempotencyKey }
  });

  // Async replication to other regions
  await replicateCrossRegion(event, writeResult.quorumAck);

  return { status: 'success', seq: globalSeq };
}

// Cross-region merge for reads
async function readUserEvents(userId, region) {
  const localEvents = await readRegion(userId, region);
  const remoteEvents = await Promise.all(
    otherRegions.map(r => readRegion(userId, r))
  );

  // Merge by global_seq, deduplicate by idempotency_key
  return mergeByTimestamp([...localEvents, ...remoteEvents], 'global_seq');
}
```

## Why This Is Asked
Tests understanding of CQRS pattern in real-time collaborative apps - crucial for Miro's architecture where immediate UI feedback and data consistency are both required.

## Expected Answer
Strong candidate will explain: Command side receives shape update request, validates permissions, persists to database, emits ShapeUpdated event. Query side maintains read model for fast UI rendering. Event-driven architecture ensures eventual consistency across all connected clients.

## Code Example
```typescript
// Command
class UpdateShapePositionCommand {
  constructor(public shapeId: string, public x: number, public y: number) {}
}

// Command Handler
class ShapeCommandHandler {
  async handle(command: UpdateShapePositionCommand) {
    const shape = await this.repo.findById(command.shapeId);
    shape.updatePosition(command.x, command.y);
    await this.repo.save(shape);

    // Emit event for query side
    this.eventBus.emit(new ShapeUpdated(shape.id, shape.x, shape.y));
  }
}

// Query side optimized for UI
class ShapeReadModel {
  async getShape(shapeId: string) {
    return this.readDb.shapes.find(shapeId);
  }
}
```

## Follow-up Questions
